import {translateTree,observeTranslations,language} from './i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(c/100),params=new URLSearchParams(location.search),token=params.get('token'),host=document.querySelector('[data-invoice]');const code=params.get('lang')||'en';globalThis.satinLanguageOverride=code;document.documentElement.lang=code;document.documentElement.dir=code==='fa'?'rtl':'ltr';document.querySelector('[data-invoice-language]').value=code;document.querySelector('[data-invoice-language]').onchange=e=>{params.set('lang',e.target.value);location.search=params;};observeTranslations(document.body);
try{const r=await fetch('/api/invoice?token='+encodeURIComponent(token)),v=await r.json();if(!r.ok)throw Error(v.error);const i=v.invoice;document.title=(i.title||'Invoice')+' · Satin Graphic';host.innerHTML=`<article class="panel"><div class="toolbar"><div><span class="pill">${esc(i.status.replaceAll('_',' '))}</span><h1 data-no-translate>${esc(i.title||'Invoice')}</h1><p>SG-${i.id.slice(0,8).toUpperCase()}</p></div><button data-print>Print / PDF</button></div><div class="form-grid"><div><h3>From</h3><p data-no-translate>${esc(i.seller?.name||'Satin Graphic')}<br>${esc(i.seller?.address||'')}<br>${esc(i.seller?.email||'info@satingraphic.ca')}<br>${esc(i.seller?.phone||'')}<br>${esc(i.seller?.taxId||'')}</p></div><div><h3>Bill to</h3><p data-no-translate>${esc(i.customer)}<br>${esc(i.business)}<br>${esc(i.address)}<br>${esc(i.email)}</p>${i.dueDate?`<p><span>Due date</span>: ${esc(i.dueDate)}</p>`:''}</div></div><div class="scroll"><table><thead><tr><th>Item / description</th><th>Quantity</th><th>Price</th><th>Tax</th><th>Total</th></tr></thead><tbody>${i.items.map(x=>`<tr><td data-no-translate>${esc(x.name||'')}<br>${esc(x.description)}</td><td>${x.quantity}</td><td>${money(Math.round(x.price*100))}</td><td>${x.taxable!==false?i.tax+'%':'—'}</td><td>${money(x.lineTotal??Math.round(x.quantity*x.price*100))}</td></tr>`).join('')}</tbody></table></div><div class="invoice-summary">${[['Subtotal',i.subtotal],['Discount',-(i.discountAmount||0)],['Before tax',i.net??i.subtotal],['Tax',i.taxAmount??i.total-i.subtotal],['Total',i.total],['Required deposit',i.depositAmount??i.total],['Paid',i.paid],['Remaining balance',i.balance]].map(([l,v])=>`<div><span>${l}</span><b>${money(v)}</b></div>`).join('')}</div><p data-no-translate>${esc(i.notes)}</p>${i.terms?`<p data-no-translate style="white-space:pre-line">${esc(i.terms)}</p>`:''}${i.payments.length?`<h3>Payments received</h3>${i.payments.map(p=>`<p>${money(p.amount)} · ${esc(p.method)} · ${new Date(p.created_at).toLocaleDateString()}</p>`).join('')}`:''}</article>${i.status==='cancelled'?'<p>Invoice cancelled.</p>':i.balance===0?'<div class="panel"><h2>Invoice paid</h2><p>Thank you. No balance remains.</p></div>':`<section class="panel payment-panel"><h2>Pay Invoice</h2><label>Payment amount<select data-stage><option value="deposit">${i.paid?'Next payment':'Deposit'} · ${money(i.dueNow)}</option><option value="balance">Remaining balance · ${money(i.balance)}</option></select></label><div class="toolbar">${v.providers.map(p=>`<button disabled>${esc(p.label)}</button>`).join('')}</div><p>Online payment is not connected yet. Contact Satin Graphic to arrange payment.</p><a href="mailto:info@satingraphic.ca">info@satingraphic.ca</a><p class="muted">This invoice link stays available for future payments.</p></section>`}`;host.querySelector('[data-print]').onclick=()=>print();translateTree(document.body);if(params.get('print')==='1')setTimeout(()=>print(),300);}catch(e){host.innerHTML='<div class="panel"><h2>Invoice unavailable</h2><p>'+esc(e.message)+'</p></div>';translateTree(document.body);}
